def lowerBiTreeError (hp : p ≠ ∞) (d : DyadicIndex → DyadicIndex → 𝕜) :
    MixedNorm 𝕜 p →L[𝕜] MixedNorm 𝕜 p :=
  (∑' k, lowerDiagonalErrorTerm (𝕜 := 𝕜) (p := p) hp d k) + (∑' k, lowerCoordinateErrorTerm (𝕜 := 𝕜) (p := p) hp d k)

